<?php
$status=$_GET['status']??'';$mensagem=$_GET['msg']??'';$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><div class="container-fluid py-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="mb-1"><i class="bi bi-box-seam me-2"></i>Aço</h2><div class="text-body-secondary">Cadastro dos produtos de aço utilizados pelo sistema.</div></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalAco" onclick="novoAco()"><i class="bi bi-plus-lg me-1"></i>Novo aço</button></div><?php if($status==='salvo'): ?><div class="alert alert-success alert-dismissible fade show">Registro salvo com sucesso.<button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?><?php if($status==='excluido'): ?><div class="alert alert-success alert-dismissible fade show">Registro excluído com sucesso.<button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?><?php if($status==='erro'): ?><div class="alert alert-danger alert-dismissible fade show"><?=$e($mensagem)?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?><?php include __DIR__.'/componentes/tabela.php'; ?></div><?php include __DIR__.'/componentes/formulario.php'; ?><script>
function novoAco(){['aco_id','aco_codigo','aco_descricao','aco_grupo'].forEach(id=>document.getElementById(id).value='');document.getElementById('aco_especial').value='0';document.getElementById('aco_peso').value='0';document.getElementById('aco_espessura').value='0';document.getElementById('aco_ativo').value='1';document.getElementById('tituloModalAco').textContent='Novo aço';}
function editarAco(r){for(const [id,k] of [['aco_id','id'],['aco_codigo','codigo'],['aco_descricao','descricao'],['aco_grupo','grupo'],['aco_especial','especial'],['aco_peso','peso_liquido'],['aco_espessura','espessura'],['aco_ativo','ativo']])document.getElementById(id).value=r[k]??'';document.getElementById('tituloModalAco').textContent='Editar aço';bootstrap.Modal.getOrCreateInstance(document.getElementById('modalAco')).show();}
function confirmarExclusaoAco(){return confirm('Excluir este aço/produto? A exclusão só será permitida se não houver registros vinculados.');}
document.addEventListener('DOMContentLoaded',()=>{const t=new DataTable('#tabelaAcos',{paging:false,scrollY:'60vh',scrollCollapse:true,order:[[0,'asc']],columnDefs:[{targets:7,orderable:false,searchable:false}],language:{emptyTable:'Nenhum registro cadastrado.',zeroRecords:'Nenhum registro encontrado.'}});document.querySelectorAll('#tabelaAcos thead tr.filters th').forEach((th,i)=>{const el=th.querySelector('input,select');if(!el)return;el.addEventListener('click',e=>e.stopPropagation());el.addEventListener('keyup',()=>t.column(i).search(el.value).draw());el.addEventListener('change',()=>t.column(i).search(el.value).draw());});});
</script>